/// One event of [`sync_now`].
class SyncEvent {
  /// The stage.
  final SyncStage stage;

  /// A one-line description (or the error on `Failed`).
  final String message;

  /// The tip (from `Probing` on).
  final PlatformInt64 tip;

  /// The height synced to (`Done`).
  final PlatformInt64 syncHeight;

  /// Yellowback usable on this server (from `Probing` on).
  final bool yellowbackUsable;

  /// Overall progress 0..=100 (transparent scan to 10, private scan 10..95, memos, done).
  final int percent;

  /// The height the private wallet is scanned to.
  final PlatformInt64 shieldedHeight;

  /// Private sending is available (scanned to the tip).
  final bool shieldedSendable;

  /// On `Done`: why the private sync did not run or failed, empty when it succeeded (the
  /// transparent sync still counts; YED and transparent YEC are unaffected).
  final String shieldedMessage;

  const SyncEvent({
    required this.stage,
    required this.message,
    required this.tip,
    required this.syncHeight,
    required this.yellowbackUsable,
    required this.percent,
    required this.shieldedHeight,
    required this.shieldedSendable,
    required this.shieldedMessage,
  });

  @override
  int get hashCode =>
      stage.hashCode ^
      message.hashCode ^
      tip.hashCode ^
      syncHeight.hashCode ^
      yellowbackUsable.hashCode ^
      percent.hashCode ^
      shieldedHeight.hashCode ^
      shieldedSendable.hashCode ^
      shieldedMessage.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is SyncEvent &&
          runtimeType == other.runtimeType &&
          stage == other.stage &&
          message == other.message &&
          tip == other.tip &&
          syncHeight == other.syncHeight &&
          yellowbackUsable == other.yellowbackUsable &&
          percent == other.percent &&
          shieldedHeight == other.shieldedHeight &&
          shieldedSendable == other.shieldedSendable &&
          shieldedMessage == other.shieldedMessage;
}

/// A stage of [`sync_now`].
enum SyncStage {
  /// Opening the channel.
  connecting,

  /// `GetLightdInfo` + `GetYellowbackInfo`.
  probing,

  /// The §3.2 loop.
  scanning,

  /// The private (Sapling) scan: `percent`, `shielded_height` move.
  shieldedScanning,

  /// Fetching the memos and status of private transactions.
  shieldedMemos,

  /// Finished; `tip` and `sync_height` are set.
  done,

  /// Failed; `message` is set.
  failed,
}

/// One own vault as `GetVault` last reported it (the Yellowback screen, plan §5.3).
class VaultSummary {
  /// The mint txid (the vault outpoint is `txid:0`).
  final String vaultTxid;

  /// `ACTIVE`, `VOID`, `CLOSED`, `CLAIMED`.
  final String status;

  /// The owner address, `ye…` form (an own key).
  final String ownerAddress;

  /// The term class letter.
  final String termClass;

  /// Cents minted (the debt).
  final PlatformInt64 cents;

  /// Collateral, zat.
  final PlatformInt64 collateralZat;

  /// `lockHeight`.
  final PlatformInt64 lockHeight;

  /// `claimHeight`.
  final PlatformInt64 claimHeight;

  /// `mintHeight`.
  final PlatformInt64 mintHeight;

  /// The last synced height the flags below were judged at.
  final PlatformInt64 tip;

  /// `ACTIVE` or `VOID`: still spendable by its owner.
  final bool open;

  /// `ACTIVE` and `tip >= lockHeight`: [`redeem`] builds the owner-path REDEEM.
  final bool redeemable;

  /// Blocks until `lockHeight` (0 once reached).
  final PlatformInt64 blocksUntilRedeem;

  /// `VOID`: [`redeem`] releases the collateral without a payload.
  final bool releasable;

  /// `claimable` as the node judged it at its tip (a liquidator may take it).
  final bool claimable;

  /// `underwaterAt`, micro-USD per YEC (0 when undefined).
  final PlatformInt64 underwaterAtMicroUsd;

  /// The last sync's `pMint` is at or below `underwaterAt`: the warning.
  final bool underwater;

  /// `closeHeight`, 0 while open.
  final PlatformInt64 closeHeight;

  /// `closingTxid`, empty while open.
  final String closingTxid;

  /// `voidReason`, empty unless VOID.
  final String voidReason;

  const VaultSummary({
    required this.vaultTxid,
    required this.status,
    required this.ownerAddress,
    required this.termClass,
    required this.cents,
    required this.collateralZat,
    required this.lockHeight,
    required this.claimHeight,
    required this.mintHeight,
    required this.tip,
    required this.open,
    required this.redeemable,
    required this.blocksUntilRedeem,
    required this.releasable,
    required this.claimable,
    required this.underwaterAtMicroUsd,
    required this.underwater,
    required this.closeHeight,
    required this.closingTxid,
    required this.voidReason,
  });

  @override
  int get hashCode =>
      vaultTxid.hashCode ^
      status.hashCode ^
      ownerAddress.hashCode ^
      termClass.hashCode ^
      cents.hashCode ^
      collateralZat.hashCode ^
      lockHeight.hashCode ^
      claimHeight.hashCode ^
      mintHeight.hashCode ^
      tip.hashCode ^
      open.hashCode ^
      redeemable.hashCode ^
      blocksUntilRedeem.hashCode ^
      releasable.hashCode ^
      claimable.hashCode ^
      underwaterAtMicroUsd.hashCode ^
      underwater.hashCode ^
      closeHeight.hashCode ^
      closingTxid.hashCode ^
      voidReason.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is VaultSummary &&
          runtimeType == other.runtimeType &&
          vaultTxid == other.vaultTxid &&
          status == other.status &&
          ownerAddress == other.ownerAddress &&
          termClass == other.termClass &&
          cents == other.cents &&
          collateralZat == other.collateralZat &&
          lockHeight == other.lockHeight &&
