/// The funding of a YEC send.
enum YecFunding {
  /// Transparent `YEC` (and, with `send_everything`, `FEE_RESERVE`) outputs.
  transparent,

  /// Private (Sapling) notes.
  shielded,
}

/// A YEC send, before confirmation.
class YecPreview {
  /// Pass to [`send_yec_confirm`].
  final String previewId;

  /// The recipient as given.
  final String to;

  /// The amount actually sent, zat.
  final PlatformInt64 amountZat;

  /// The amount was raised by one zat off `TOKEN_VALUE`.
  final bool amountBumped;

  /// The fee, zat.
  final PlatformInt64 feeZat;

  /// The change, zat.
  final PlatformInt64 changeZat;

  /// Number of inputs.
  final int inputs;

  /// The fee reserve was spent (`send_everything`).
  final bool usesReserve;

  /// YEC that stays reserved for YED fees after this send, zat.
  final PlatformInt64 keepsReservedZat;

  /// `nExpiryHeight`.
  final int expiryHeight;

  /// The txid the transaction will have (empty for a private send: its proofs are made at
  /// confirm, so the txid is known only then).
  final String txid;

  /// Where the money comes from (privacy first, `build::yec_private`).
  final YecFunding funding;

  /// Private funds go to a transparent address: the amber line "This send leaves the
  /// private pool".
  final bool revealsShielded;

  /// The memo that will be sent (private recipients only).
  final String? memo;

  /// A private send whose proving parameters are not downloaded yet: run
  /// [`download_params`] before [`send_yec_confirm`].
  final bool paramsNeeded;

  const YecPreview({
    required this.previewId,
    required this.to,
    required this.amountZat,
    required this.amountBumped,
    required this.feeZat,
    required this.changeZat,
    required this.inputs,
    required this.usesReserve,
    required this.keepsReservedZat,
    required this.expiryHeight,
    required this.txid,
    required this.funding,
    required this.revealsShielded,
    this.memo,
    required this.paramsNeeded,
  });

  @override
  int get hashCode =>
      previewId.hashCode ^
      to.hashCode ^
      amountZat.hashCode ^
      amountBumped.hashCode ^
      feeZat.hashCode ^
      changeZat.hashCode ^
      inputs.hashCode ^
      usesReserve.hashCode ^
      keepsReservedZat.hashCode ^
      expiryHeight.hashCode ^
      txid.hashCode ^
      funding.hashCode ^
      revealsShielded.hashCode ^
      memo.hashCode ^
      paramsNeeded.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is YecPreview &&
          runtimeType == other.runtimeType &&
          previewId == other.previewId &&
          to == other.to &&
          amountZat == other.amountZat &&
          amountBumped == other.amountBumped &&
          feeZat == other.feeZat &&
          changeZat == other.changeZat &&
          inputs == other.inputs &&
          usesReserve == other.usesReserve &&
          keepsReservedZat == other.keepsReservedZat &&
          expiryHeight == other.expiryHeight &&
          txid == other.txid &&
          funding == other.funding &&
          revealsShielded == other.revealsShielded &&
          memo == other.memo &&
          paramsNeeded == other.paramsNeeded;
}

